NAME = 'PohnOld: Old Public Domain Pohnpeian Bible'
BOOK = 'I Thessalonians'

CHAPTERS = {
    1: {
        1: 'PAULUS, o Silwanus, o Timoteus ong momodisou en Tesalonik, me ren Kot Sam o Kaun Iesus Kristus. Mak o popol en mi re omail!',
        2: 'Se kin poden danke Kot ki komail karos o tamataman kin komail ni at kapakap akan.',
        3: 'O se kin tamatamanda omail wiawia kan ni poson, o omail dodok ni limpok, o omail kanongama ni kaporoporeki atail Kaun Iesus Kristus sansal ong Kot o Sam atail.',
        4: 'Pwe ri ai kan o kompoke pan Kot akan, se asa duen omail lipilipil re a,',
        5: 'Pwe at rongamau lel ong komail er, kaidin nin lokaia ta, a pil ni manaman o Ngen saraui, o ni kamelelepa kaualap, pwe komail asa song en aramas da kit re omail pweki komail.',
        6: 'A komail ale sanger kit o sang Kaun o, ni omail aleer masan o ni kamekam kaualap o ni peren en Ngen saraui.',
        7: 'Komail wialar kilel en saulang karos mi Masetonien o Akaia.',
        8: 'Pwe sang re omail masan en Kaun o kaparaparalar, kaidin nan Masetonien o Akaia eta, pwe pil wasa karos omail poson Kot lokila ia; ari, solar me se pan inda.',
        9: 'Pwe pein irail kaire kin kit, duen at pwaralang komail me pwaida, o duen omail wuki ong Kot sang dikedik en ani kan, pwen papang Kot, me udan maur o melel.',
        10: 'O auiaui sapwilim a Ol sang nanlang, me a kotin kaiasada sang ren me melar akan, Iesus, me kotin dore kitail sang ni ongiong en Kot, me pan sansaldo.',
    },
    2: {
        1: 'PWE pein komail asa, ri ai kan, duen at pwaralang komail kaidin me so kadepa.',
        2: 'A murin at kamekam nan Pilipi o at kalokolok wasa o, duen me komail asa, kit aimaki atail Kot padaki ong komail rongamau en Kot ni apwal laud.',
        3: 'Pwe at panapanaui komail sota wiaui ni kotaue, de samin, de widing.',
        4: 'Pwe duen kit ale sang ren Kot en padaki rongamau, iduen at padak kin wiaui, kaidin pwen konekonlar ren aramas akan, a Kot me kotin kasauiada mongiong it.',
        5: 'Sota eu ansau me se lingkapinga komail, duen me komail asa, de norok kapwa, Kot me saunkadede en mepukat.',
        6: 'Se pil sota rapaki konekon ren aramas akan, ma re omail de ren akai. A se pan kak katoutoui komail, pwe kit wanporon en Kristiis akan.',
        7: 'Ari so, kit kin materok nan pung omail dueta li en kamait amen, me kin apwali na seri kan.',
        8: 'Iduen at ngong kin komail melel, se mauki katungole kin komail rongamau en Kot, a kaidin i eta, a pein maur at, pwe komail wialar kompoke pat.',
        9: 'Ri ai kan, komail kin tamanda duen at dodok o at apwal akan. Pwe se dodok ni ran o ni pong, pwen der katoutoui amen komail, o se padaki ong komail rongamau en Kot.',
        10: 'Komail o Kot at saunkadede duen at makelekel, o pung, o inen re omail me poson akan.',
        11: 'O duen komail asa, me kit panaui o kamekamait amen amen re omail dueta papa men wiai ong na seri kan.',
        12: 'O se padaki ong komail er, me komail en alu inen wei ta, duen me kon ong Kot, me kotin molipe komail ong pein a wei o pein a lingan.',
        13: 'I me se kin poden danke Kot, pwe ni omail aleer masan en Kot, komail aleer kaidin dueta padak en aramas akan, pwe dueta masan en Kot melel, me pil kin dodok nan lol omail me poson akan.',
        14: 'Pwe ri ai kan, komail ale sanger momodisou en Kot akan nan Iudäa ren Kristus Iesus; pwe komail kamekame ren toun omail wei, dueta irail me kamekame ren Sus akan.',
        15: 'Me pil kamatalar Kaun Iesus, o saukop akan, me re kaloke, o re sota konekon ren Kot, o re kin palian aramas akan karos.',
        16: 'O re kainapwi sang kit, ender padak ong men liki kan, pwe ren der maurela, pwe re kin kadirela dip arail ansau karos, a ongiong mi po’rail.',
        17: 'A kit ri ai kan ni at doo wei sang komail ansau kis ni pali war at, a kaidin ni mongiong it, se ap nantiong o inong iong melel kilang mas omail.',
        18: 'I me se men pwar wong komail, ngai Paulus pan mepak o pan riapak, a Satan karompa kit.',
        19: 'Pwe is me kapore pat, de kaperen pat, de kapinga pat? Kaidin komail mon Kaun patail Iesus ni a kotido?',
        20: 'Pwe komail kalinga pat o kaperen pat.',
    },
    3: {
        1: 'I ME se solar kak nenen la, pwe se maukida kelepala nan Aten,',
        2: 'Ap kadar wong komail Timoteus ri atail o papan Kot ni rongamau en Kristus, pwen katenge komail o kamait komail la iran omail poson.',
        3: 'Pwe sota amen en luet kila kamekam wet, pwe pein komail asa, mepukat kileledier ong kitail.',
        4: 'Pwe ni at mimi re omail, se kokopki dong komail kamekam; duen a pwaidar o duen me komail asa.',
        5: 'I me i solar kak nenenla, a i ilakila, pwe i en asa, duen omail poson, ma men kasongesong so kasongesong komail, o ma at dodok sota pan dodok mal.',
        6: 'A metet ni en Timoteus pwara dong kin sang re omail, o padaki ong kit rong mau duen omail poson o limpok, o duen omail tamataman kit ansau karos, o duen komail men kilang kit, i dueta kit kin inong iong kilang komail.',
        7: 'Ri ai kan, kit ap kamait kilar komail ni at kamekam o apwal akan ki omail poson.',
        8: 'Pwe ansau wet kit maureda, ma komail poden tengedi ong Kaun o.',
        9: 'Pwe ia danke me sen dankeki Kot pweki komail, me pan ras ong peren, me se peren kida mon Kot ki komail?',
        10: 'Se kin poden kapakapa kin komail ni pong ni ran o ngidingidiki, sen kilang mas omail o kaunsokala omail poson.',
        11: 'Ari, pein Kot, o Sam atail, o atail Kaun Iesus en kotin kalua kit wong komail.',
        12: 'A Kaun o en kotin kangedere komail la o kalaudela omail limpok nan pung omail o ong amen amen dueta kit ong komail.',
        13: 'O kotin katengeteng mongiong omail pwen mau melel, ni saraui mon Kot o Sam atail ong ni ran en atail Kaun Iesus, me pan kotido o sapwilim a saraui kan karos iang i.',
    },
    4: {
        1: 'ARI, ri ai kan, se pil poeki re omail o panaui kin komail Kaun Iesus, duen me komail aleer sang kit, o duen me komail en kekeideki wei, o kaperenda Kot, iduen omail kakairida.',
        2: 'Pwe komail asa duen kusoned akan, me se pang ong komail ren Kaun Iesus.',
        3: 'Pwe iet kupur en Kot, omail sarauila, pwe komail en liki sang nenek.',
        4: 'Amen amen en kanai ong pein war a, pwen saraui o wau o liki sang inong sued,',
        5: 'Kaidin ni dender ong inong sued duen men liki kan, me so asa Kot;',
        6: 'O sota me pan piti de kasapungi ong ri a ni meakot, pwe Kaun o pan kotin iki ong i, duen me kit inda o kadede ong komail er mas o.',
        7: 'Pwe Kot sota molipei kitail ong samin, a pwen saraui.',
        8: 'A ma amen komail pan mamaleki mepukat, kaidin aramas me a pan mamaleki pwe Kot, me pil kotiki ong komail er sapwilim a Ngen saraui.',
        9: 'A duen limpok en saulang, menda i en intingki wong komail, pwe pein komail padakki sang ren Kot, me komail en poke pena.',
        10: 'Nan met komail kin wiai ong saulang karos, me mimi Masetonien pon. A se panaui kin komail ri at akan, komail en kakairida.',
        11: 'O komail nenenla o inong iong apwali pein omail dodok, kadokeki pein pa omail, duen me se padaki ong komail er,',
        12: 'Pwe komail en sansal mau mon me mi liki kan, o komail der mau ong amen en apwali komail.',
        13: 'Ri ai kan, se sota men oki sang komail duen me mairelar akan, pwe komail der insensued dueta irail, me sota ar kaporopor.',
        14: 'Pwe ma kitail kamelele, me Iesus matala ap iasadar, nan iduen me mairelar ren Iesus, Kot pil pan kalua ir ala re a.',
        15: 'Pwe ieteten me se indang komail ni masan en Kaun o, kit me memaureta lao Kaun o pan kotin pwarado, sota pan ko wei mon me mair akan.',
        16: 'Pwe pein Kaun o pan kotido sang nanlang ki masan laud, o kapiti en toulang lapalap amen, o koronete en Kot; me melar akan ren Kristus ap pan maureda mas.',
        17: 'Kit me memaureta luadi ap pan iang ir peukadala nan dapok kan, ko ong ren Kaun o nan wäwä, kitail ap pan mimieta ren Kaun o kokolata.',
        18: 'Komail ari kamaiteki komail la padak pot et.',
    },
    5: {
        1: 'A DUEN ansau o auer, ri ai kan, menda i en inting wong komail.',
        2: 'Pwe pein komail asa mau, me ran en Kaun o pan pwarado dueta lipirap amen ni pong.',
        3: 'Pwe irail lao pan inda: A muei mau, o sota apwal kot mia, i ansau kaupa pan lel ong irail dueta li lisean amen; a irail sota pan pitila.',
        4: 'A komail ri ai kan, solar mi ni rotorot, pwe ran o de konodi komail duen lipirap amen.',
        5: 'Komail karos seri en marain, o seri en ran. Kitail so kisan pong o rotorot.',
        6: 'Kitail ari ender mamair dueta me tei kan, a kitail en masamasan o daulikin.',
        7: 'Pwe me mair, kin mamair ni pong, o me sokolar, kin sokolar ni pong.',
        8: 'A kitail, me kisan ran, en liki sang, til wong nan pere pan marmar en poson o limpok, o lisoropeki kaporopor pan maur.',
        9: 'Pwe kaidin ongiong, me Kot kotin kileledi ong kitail, a sen konodi maur soutuk ki atail Kaun Iesus Kristus,',
        10: 'Me mata kin kitail er, pwe ma kitail papat de mamair, en maur pena re a.',
        11: 'Komail ari panau o sauas pena nan pung omail duen me komail kin wia.',
        12: 'A se poeki re omail, ri ai kan, komail, en apwali me kin dodok nan pung omail, o me kaun komail da pan Kaun o, o me kin panaui komail.',
        13: 'Komail kaka kin ir kaualap ni limpok, pweki ar wiawia; o komail popol pena.',
        14: 'Se panaui kin komail, ri ai kan, komail en kapung ong me katiwo kan, o kamait, me ar poson tikitik, o apapwali me luet akan, o kanongama ong karos.',
        15: 'Komail masamasan, pwe amen ender depukki ong amen me sued me sued, a en inong iong me mau eta nan pung omail o ong amen amen.',
        16: 'Komail pereperen ansau karos.',
        17: 'Kapakapta soutuk.',
        18: 'Komail danke ni meakaros, pwe iduen kupur en Kot ren Kristus Iesus ong komail.',
        19: 'Der kakundi Ngen.',
        20: 'Der mamaleki deideikop akan.',
        21: 'Kasosong ong meakan karos, ap koledi me mau.',
        22: 'Liki sang song en sued karos.',
        23: 'A Kot en popol en kasaraui komail la kaualap, ngen omail, o mongiong omail, o war omail en nekinek mau ong en atail Kaun Iesus Kristus a pwarado.',
        24: 'Melel i, me kotin molipe komail er, me pan pil wiada.',
        25: 'Ri ai kan kapakapa kin kit.',
        26: 'Ranamauki ri at akan karos metik saraui.',
        27: 'I kauki ong Kaun, me komail pan wadok kisin likau kis et ong saulang saraui kan karos.',
        28: 'Mak en atail Kaun Iesus Kristus en mi re omail!',
    },
}
